<?php /** @var array $customRoles @var array $capabilities @var \Core\Security\Csrf $csrf */ ?>
<section class="status-strip"><div class="status-chip"><strong>3</strong><span>Built-in roles</span></div><div class="status-chip"><strong><?= count($customRoles) ?></strong><span>Custom roles</span></div><div class="status-chip"><strong><?= count($capabilities) ?></strong><span>Capabilities</span></div></section>
<div class="card"><h2 style="margin-top:0">Built-in roles</h2><p><strong>Owner</strong> has every capability and cannot be removed. <strong>Admin</strong> operates the site and publishes content. <strong>Editor</strong> creates content and submits it for approval.</p></div>
<div class="card"><div class="card-heading"><div><h2>Custom roles</h2><p class="card-subtitle">Grant only the capabilities a person needs for their responsibilities.</p></div></div><?php if(!$customRoles): ?><div class="empty-state"><strong>No custom roles</strong><span>Built-in roles remain available, or create a more focused role below.</span></div><?php endif; ?><?php foreach($customRoles as $role): $selected=json_decode((string)$role['capabilities_json'],true)?:[]; ?><details class="card disclosure"><summary><strong><?= e($role['label']) ?></strong> <code><?= e($role['slug']) ?></code> <span class="badge neutral"><?= count($selected) ?> permissions</span></summary><form method="post" class="disclosure-body"><?= $csrf->field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="slug" value="<?= e_attr($role['slug']) ?>"><label>Label</label><input name="label" value="<?= e_attr($role['label']) ?>" required><div class="option-grid"><?php foreach($capabilities as $cap): ?><label class="choice-row compact"><input type="checkbox" name="capabilities[]" value="<?= e_attr($cap) ?>" <?= in_array($cap,$selected,true)?'checked':'' ?>><span><?= e($cap) ?></span></label><?php endforeach; ?></div><button class="btn">Save role</button></form><form method="post" class="danger-zone action-bar"><?= $csrf->field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="slug" value="<?= e_attr($role['slug']) ?>"><span>Remove this role after reassigning its administrators.</span><button class="btn small danger" data-confirm="Delete this custom role? Reassign any administrators using it first.">Delete role</button></form></details><?php endforeach; ?>
<details><summary class="btn secondary">Create custom role</summary><form method="post" style="margin-top:1rem"><?= $csrf->field() ?><input type="hidden" name="action" value="save"><div class="inline-fields"><div><label>Slug</label><input name="slug" maxlength="20" required placeholder="marketing"></div><div><label>Label</label><input name="label" required placeholder="Marketing manager"></div></div><div class="grid2"><?php foreach($capabilities as $cap): ?><label><input type="checkbox" style="width:auto" name="capabilities[]" value="<?= e_attr($cap) ?>"> <?= e($cap) ?></label><?php endforeach; ?></div><button class="btn">Create role</button></form></details></div>
